"""specs_s200046.py - Sonnet-w2 family X2 (generated by mkfamX2.py): 0x41e290 returns a heap object or 0; BASE records the SEH chain and its arguments. Fake outer SEH records 0-2; fs:[0] compared."""
from pilot import S
from recruits_util import rnd, clear_hooks, hook_rec, seh_record, seh_chain


def _mk(base):
    def gen(c):
        clear_hooks(c)
        seh_chain(c, c.rng.choice([0, 1, 2]))
        r = c.rng
        p = r.choice([0, rnd(c, 0x40), rnd(c, 0x40)])
        hook_rec(c, 0x41e290, 1, ret=p, pop=0, side=seh_record(c, 2))
        hook_rec(c, base, 2, ret=r.getrandbits(32), pop=8, this=True, side=seh_record(c, 2))
        return [r.getrandbits(32), r.getrandbits(32)]
    return gen


S(0x603dd0, 'GUESS famX2 0x603dd0', 'fastcall', None, ret='eax', gen=_mk(0x603430), note='batch200046')
S(0x6043c0, 'GUESS famX2 0x6043c0', 'fastcall', None, ret='eax', gen=_mk(0x6041e0), note='batch200046')
